import crypto from 'crypto';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import type { SsrReq, SsrRes } from './types';

/**
 * Tokens are valid for 20 minutes. Cached at module scope and reused across
 * lambda invocations. Refreshed after 15 minutes.
 */
let marketingCloudToken = '';
let marketingCloudTokenExpiration = new Date();

type MarketingCloudConfig = {
  clientId: string | undefined;
  clientSecret: string | undefined;
  subdomain: string | undefined;
  templateId: string | undefined;
  magicLink: string;
};

function generateUniqueId(): string {
  return crypto.randomBytes(16).toString('hex');
}

/**
 * Sends an email to a specified contact using the Marketing Cloud API. The template email must have a
 * `%%magic-link%%` personalization string inserted.
 * https://help.salesforce.com/s/articleView?id=mktg.mc_es_personalization_strings.htm&type=5
 */
async function sendMarketingCloudEmail(emailId: string, marketingCloudConfig: MarketingCloudConfig): Promise<unknown> {
  const { clientId, clientSecret, subdomain } = marketingCloudConfig;
  if (!clientId || !clientSecret || !subdomain) {
    throw new Error('Marketing Cloud credentials are missing: clientId, clientSecret, and subdomain are required.');
  }

  // Refresh token if expired
  if (new Date() > marketingCloudTokenExpiration) {
    const tokenUrl = `https://${subdomain}.auth.marketingcloudapis.com/v2/token`;
    const tokenResponse = await fetch(tokenUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        grant_type: 'client_credentials',
        client_id: clientId,
        client_secret: clientSecret,
      }),
    });

    if (!tokenResponse.ok)
      throw new Error(
        'Failed to fetch Marketing Cloud access token. Check your Marketing Cloud credentials and try again.',
      );

    const { access_token } = (await tokenResponse.json()) as { access_token: string };
    marketingCloudToken = access_token;
    // Set expiration to 15 mins
    marketingCloudTokenExpiration = new Date(Date.now() + 15 * 60 * 1000);
  }

  // Send the email
  const emailUrl = `https://${subdomain}.rest.marketingcloudapis.com/messaging/v1/email/messages/${generateUniqueId()}`;
  const emailResponse = await fetch(emailUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${marketingCloudToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      definitionKey: marketingCloudConfig.templateId,
      recipient: {
        contactKey: emailId,
        to: emailId,
        attributes: { 'magic-link': marketingCloudConfig.magicLink },
      },
    }),
  });

  if (!emailResponse.ok) throw new Error('Failed to send email to Marketing Cloud');

  return emailResponse.json();
}

/**
 * Generates a unique ID, constructs an email message URL, and sends the email to the specified contact
 * using the Marketing Cloud API.
 */
export async function emailLink(emailId: string, templateId: string, magicLink: string): Promise<unknown> {
  if (!process.env.MARKETING_CLOUD_CLIENT_ID) {
    console.warn('MARKETING_CLOUD_CLIENT_ID is not set in the environment variables.');
  }

  if (!process.env.MARKETING_CLOUD_CLIENT_SECRET) {
    console.warn(' MARKETING_CLOUD_CLIENT_SECRET is not set in the environment variables.');
  }

  if (!process.env.MARKETING_CLOUD_SUBDOMAIN) {
    console.warn('MARKETING_CLOUD_SUBDOMAIN is not set in the environment variables.');
  }

  const marketingCloudConfig: MarketingCloudConfig = {
    clientId: process.env.MARKETING_CLOUD_CLIENT_ID,
    clientSecret: process.env.MARKETING_CLOUD_CLIENT_SECRET,
    magicLink: magicLink,
    subdomain: process.env.MARKETING_CLOUD_SUBDOMAIN,
    templateId: templateId,
  };
  return sendMarketingCloudEmail(emailId, marketingCloudConfig);
}

/**
 * Builds the magic-link URL for the given landing path, sends the email via Marketing Cloud,
 * and writes the API response to the Express response.
 */
type LoginConfig = {
  login?: {
    resetPassword?: { landingPath?: string };
    passwordless?: { landingPath?: string };
  };
};

export async function sendMagicLinkEmail(
  req: SsrReq,
  res: SsrRes,
  landingPath: string,
  emailTemplate: string,
  redirectUrl?: string,
): Promise<void> {
  const { app } = getConfig() as { app: LoginConfig };

  // Extract the base URL from the request
  const host = req.get('host');
  if (!host) throw new Error('Cannot construct magic link: missing Host header');
  const base = `${req.protocol}://${host}`;

  // Extract the email_id and token from the request body
  const { email_id, token } = req.body;

  // Construct the magic link URL
  let magicLink = `${base}${landingPath}?token=${encodeURIComponent(token)}`;
  if (landingPath === app.login?.resetPassword?.landingPath) {
    // Add email query parameter for reset password flow
    magicLink += `&email=${encodeURIComponent(email_id)}`;
  }
  if (landingPath === app.login?.passwordless?.landingPath && redirectUrl) {
    magicLink += `&redirect_url=${encodeURIComponent(redirectUrl)}`;
  }

  // Call the emailLink function to send an email with the magic link using Marketing Cloud
  const emailLinkResponse = await emailLink(email_id, emailTemplate, magicLink);

  // Send the response
  res.send(emailLinkResponse);
}

/**
 * Undici connection pools for SSR upstream origins (TSD §12.1 blast-radius mitigation).
 *
 * Each pool caps the concurrent connections to one origin so a slow or flooded integration
 * cannot exhaust connections for unrelated services. Use the per-call `dispatcher` option
 * on `fetch()` calls inside ssr.js to route requests through the correct pool:
 *
 *   import {fetch} from 'undici'
 *   import {sfccPaymentsPool} from './ssr/connectionPools'
 *   const data = await fetch(url, {dispatcher: sfccPaymentsPool})
 *
 * Connection caps and timeouts are set to the TSD §12.1 planned values.
 * Validate them on Stage (§9.3) — undici emits queue-depth and connection-wait
 * metrics via diagnostic channel events for tuning.
 *
 * IMPORTANT: Booxi base URL must be confirmed with the Integration team before enabling
 * that pool. See the TODO below.
 */
import { Pool } from 'undici';

/** SLAS JWKS token validation (passwordless login, reset password). Calls are rare — jose caches the JWK set. */
export const sfccScapiPool = new Pool(
  `https://${process.env.COMMERCE_API_SHORT_CODE ?? 'COMMERCE_API_SHORT_CODE'}.api.commercecloud.salesforce.com`,
  { connections: 5, connectTimeout: 5_000, bodyTimeout: 8_000 },
);

/**
 * Payment method metadata on every checkout page SSR.
 * Separate from sfccScapiPool so a checkout traffic spike cannot consume SLAS connections.
 * TODO: Confirm the exact hostname of config.app.sfPayments.metadataUrl with the Integration team
 * and replace the placeholder origin here.
 */
export const sfccPaymentsPool = new Pool(
  `https://${process.env.SFCC_PAYMENTS_HOST ?? 'SFCC_PAYMENTS_HOST.demandware.net'}`,
  { connections: 10, connectTimeout: 5_000, bodyTimeout: 8_000 },
);

/**
 * Order history, order details, boutique/BOPIS stock check, GiveX balance check.
 * Highest cap — broadest call surface across My Account and PDP.
 */
export const mulesoftPool = new Pool(process.env.MULESOFT_BASE_URL ?? 'https://MULESOFT_BASE_URL', {
  connections: 20,
  connectTimeout: 5_000,
  bodyTimeout: 10_000,
});

/** Marketing Cloud client-credentials token exchange. Token cached at module scope for 15 min. */
export const marketingCloudAuthPool = new Pool(
  `https://${process.env.MARKETING_CLOUD_SUBDOMAIN ?? 'MARKETING_CLOUD_SUBDOMAIN'}.auth.marketingcloudapis.com`,
  { connections: 5, connectTimeout: 5_000, bodyTimeout: 15_000 },
);

/** Magic-link email send (passwordless login, reset password). Higher body timeout — email APIs can respond slowly. */
export const marketingCloudRestPool = new Pool(
  `https://${process.env.MARKETING_CLOUD_SUBDOMAIN ?? 'MARKETING_CLOUD_SUBDOMAIN'}.rest.marketingcloudapis.com`,
  { connections: 5, connectTimeout: 5_000, bodyTimeout: 15_000 },
);

/** Address autocomplete at checkout (CFD-023, CFD-030, CFD-059). Short timeouts — graceful fallback to manual entry. */
export const googlePlacesPool = new Pool('https://places.googleapis.com', {
  connections: 5,
  connectTimeout: 3_000,
  bodyTimeout: 5_000,
});

/**
 * Boutique appointment history in My Account (CRM-165–167).
 * TODO: Replace placeholder origin with confirmed Booxi base URL from the Integration team.
 */
export const booxiPool = new Pool(process.env.BOOXI_BASE_URL ?? 'https://BOOXI_BASE_URL', {
  connections: 5,
  connectTimeout: 3_000,
  bodyTimeout: 5_000,
});

